import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display inventory page and burger menu on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify inventory page is visible
    const inventoryItems = page.getByRole('region', { name: /inventory/i });
    await expect(inventoryItems).toBeVisible();

    // Verify burger menu button is visible
    const burgerMenuButton = page.getByRole('button', { name: /burger menu/i });
    await expect(burgerMenuButton).toBeVisible();

    // Verify inventory items are displayed
    const itemCards = page.getByRole('region', { name: /inventory item/i });
    await expect(itemCards).toHaveCount(6);
  });

  test('should open side menu with logout link on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify inventory page is visible
    const inventoryItems = page.getByRole('region', { name: /inventory/i });
    await expect(inventoryItems).toBeVisible();

    // Open burger menu
    const burgerMenuButton = page.getByRole('button', { name: /burger menu/i });
    await burgerMenuButton.click();

    // Verify side menu is open
    const sideMenu = page.locator('[data-testid="bm-menu"]');
    await expect(sideMenu).toBeVisible();

    // Verify logout link is visible inside the side menu
    const logoutLink = page.getByRole('link', { name: /logout/i });
    await expect(logoutLink).toBeVisible();

    // Verify logout link is clickable
    await expect(logoutLink).toBeEnabled();
  });
});
